def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def norm_pos(p):
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return None

    def step_toward(src, dst):
        if src is None or dst is None:
            return [0, 0]
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(src, dst):
        if src is None or dst is None:
            return [0, 0]
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_by_dist(points, ref, want_min=True):
        pts = [norm_pos(p) for p in (points or [])]
        pts = [p for p in pts if p is not None]
        if not pts or ref is None:
            return None
        return min(pts, key=lambda p: manhattan(p, ref)) if want_min else max(pts, key=lambda p: manhattan(p, ref))

    env = observation.get("environment_name", "resource_collection")
    self_pos = norm_pos(observation.get("self_position"))
    opp_pos = norm_pos(observation.get("opponent_position"))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    role = observation.get("self_role", "pursuer")

    if env == "pursuit_evasion":
        if role == "pursuer":
            if self_pos is not None and opp_pos is not None:
                return step_toward(self_pos, opp_pos)
            return [0, 0]
        corners = []
        if gw > 0 and gh > 0 and self_pos is not None:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
            target = best_by_dist(corners, opp_pos if opp_pos is not None else self_pos, want_min=False)
            if target is not None:
                return step_toward(self_pos, target)
        if self_pos is not None and opp_pos is not None:
            return step_away(self_pos, opp_pos)
        return [0, 0]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("opponent_territory")
            or observation.get("targets")
            or []
        )
        target = best_by_dist(targets, self_pos, want_min=True)
        if target is not None and self_pos is not None:
            return step_toward(self_pos, target)
        if gw > 0 and gh > 0 and self_pos is not None:
            center = (gw // 2, gh // 2)
            return step_toward(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = best_by_dist(resources, self_pos, want_min=True)
